const rows = $('Get Cases').all().map(i => i.json);

if (rows.length === 0) {
  return [{ json: { table: 'cases', count: 0, cases: [], summary: 'No eval cases found.' } }];
}

return [{ json: {
  table: 'cases',
  count: rows.length,
  cases: rows.map(r => ({ case_id: r.case_id, input: (r.input || '').substring(0, 200), expected_tools: r.expected_tools, prohibited_tools: r.prohibited_tools, source_thread: r.source_thread, created_at: r.created_at })),
  summary: `${rows.length} eval cases loaded.`
} }];

const input = $('Input').first().json;
const allRows = $('Get Results').all().map(i => i.json);

// Apply filters
let rows = allRows;
if (input.run_id) {
  rows = rows.filter(r => String(r.run_id) === String(input.run_id));
}
if (input.case_id) {
  rows = rows.filter(r => String(r.case_id) === String(input.case_id));
}

if (rows.length === 0) {
  return [{ json: { table: 'results', count: 0, results: [], summary: 'No results found.' + (input.run_id ? ' Run may still be in progress.' : '') } }];
}

const verdicts = rows.reduce((acc, r) => { acc[r.verdict] = (acc[r.verdict] || 0) + 1; return acc; }, {});
const dims = ['faithfulness', 'citation_validity', 'source_routing', 'completeness', 'relevance', 'format'];
const avgScores = {};
dims.forEach(d => {
  const vals = rows.map(r => parseFloat(r[d])).filter(v => !isNaN(v));
  avgScores[d] = vals.length ? (vals.reduce((a,b) => a+b, 0) / vals.length).toFixed(2) : 'N/A';
});

return [{ json: {
  table: 'results',
  count: rows.length,
  stats: { verdicts, avg_scores: avgScores },
  results: rows.map(r => ({ run_id: r.run_id, case_id: r.case_id, verdict: r.verdict, faithfulness: r.faithfulness, citation_validity: r.citation_validity, source_routing: r.source_routing, completeness: r.completeness, relevance: r.relevance, format: r.format, response: r.response, tools_called: r.tools_called })),
  summary: `${rows.length} results: ${verdicts.pass || 0} pass, ${verdicts.borderline || 0} borderline, ${verdicts.fail || 0} fail`
} }];
